SELECT wp_wc_orders.id FROM wp_wc_orders INNER JOIN wp_wc_orders_meta AS meta0 ON ( wp_wc_orders.id = meta0.order_id ) LEFT JOIN wp_wc_orders_meta AS meta1 ON ( wp_wc_orders.id = meta1.order_id AND meta1.meta_key = '_m1_status' ) INNER JOIN wp_wc_orders_meta AS meta2 ON ( wp_wc_orders.id = meta2.order_id ) INNER JOIN wp_wc_orders_meta AS meta3 ON ( wp_wc_orders.id = meta3.order_id ) LEFT JOIN wp_wc_orders_meta AS meta4 ON ( wp_wc_orders.id = meta4.order_id AND meta4.meta_key = '_m2_status' ) INNER JOIN wp_wc_orders_meta AS meta5 ON ( wp_wc_orders.id = meta5.order_id ) WHERE 1=1 AND (wp_wc_orders.status IN ('wc-pending','wc-processing','wc-on-hold','wc-completed','wc-refunded','wc-checkout-draft')) AND (wp_wc_orders.type IN ('shop_order','shop_order_refund')) AND ((((meta0.meta_key = '_m1_marker') AND ((meta1.order_id IS NULL) OR (meta2.meta_key = '_m1_status' AND meta2.meta_value NOT IN ('M1_GO')))) OR ((meta3.meta_key = '_m2_marker') AND ((meta4.order_id IS NULL) OR (meta5.meta_key = '_m2_status' AND meta5.meta_value NOT IN ('M2_GO')))))) GROUP BY wp_wc_orders.id ORDER BY wp_wc_orders.date_created_gmt DESC LIMIT 0, 20

SELECT COUNT(DISTINCT wp_wc_orders.id) FROM wp_wc_orders INNER JOIN wp_wc_orders_meta AS meta0 ON ( wp_wc_orders.id = meta0.order_id ) LEFT JOIN wp_wc_orders_meta AS meta1 ON ( wp_wc_orders.id = meta1.order_id AND meta1.meta_key = '_m1_status' ) INNER JOIN wp_wc_orders_meta AS meta2 ON ( wp_wc_orders.id = meta2.order_id ) INNER JOIN wp_wc_orders_meta AS meta3 ON ( wp_wc_orders.id = meta3.order_id ) LEFT JOIN wp_wc_orders_meta AS meta4 ON ( wp_wc_orders.id = meta4.order_id AND meta4.meta_key = '_m2_status' ) INNER JOIN wp_wc_orders_meta AS meta5 ON ( wp_wc_orders.id = meta5.order_id ) WHERE 1=1 AND (wp_wc_orders.status IN ('wc-pending','wc-processing','wc-on-hold','wc-completed','wc-refunded','wc-checkout-draft')) AND (wp_wc_orders.type IN ('shop_order','shop_order_refund')) AND ((((meta0.meta_key = '_m1_marker') AND ((meta1.order_id IS NULL) OR (meta2.meta_key = '_m1_status' AND meta2.meta_value NOT IN ('M1_GO')))) OR ((meta3.meta_key = '_m2_marker') AND ((meta4.order_id IS NULL) OR (meta5.meta_key = '_m2_status' AND meta5.meta_value NOT IN ('M2_GO'))))))
